function portfolio(){const pf=grp('portfolio');return `<section class="pg"><header class="ph"><h2>${esc(tr('Portfolio'))}</h2><p class="lead">${esc(tr('All my work in one place, organized by category.'))}</p></header><div class="catg">${pf.map(p=>`<a class="catc" href="#${p.id}"><b>${esc(tr(p.title))}</b><span>${p.folders.reduce((n,f)=>n+f.items.length,0)}</span></a>`).join('')}</div>${pf.map(p=>{const i=st.pages.indexOf(p);return `<section class="pcat pg-${p.layout}" style="--ac:${esc(acOf(p,i))}"><h3 class="pct"><a href="#${p.id}">${esc(tr(p.title))}</a></h3>${p.folders.some(f=>f.items.length)?p.folders.map((f,fi)=>f.items.length?`<div class="pfn">${esc(tr(f.name))}</div><div class="L L-${p.layout}">${figs(p,i,fi,f.items)}</div>`:'').join(''):`<p class="empty">${esc(tr('No projects in this category yet.'))}</p>`}</section>`}).join('')}</section>`}
