function reviews(){const L=st.reviews.map((r,i)=>[r,i]).filter(x=>editing()||x[0].show!==false);return `<section class="pg"><header class="ph"><h2>${esc(tr('Client Reviews'))}</h2><p class="lead">${esc(tr('What clients say about working with me.'))}</p></header>${editing()?`<p><button class="tog" data-a="radd">+ Add review</button></p>`:''}${L.length?`<div class="rv">${L.map(([r,i])=>`<figure class="it rvc${r.show===false?' off':''}">${editing()?`<div class="itb"><button data-a="rup" data-i="${i}">↑</button><button data-a="rdn" data-i="${i}">↓</button><button data-a="rvis" data-i="${i}">${r.show===false?'Show':'Hide'}</button><button data-a="rimg" data-i="${i}">+ Image</button><button data-a="rdel" data-i="${i}">Delete</button></div>`:''}${r.images.map((m,j)=>`<div class="rim"><img src="${esc(m.src)}" alt="${esc(r.title||'Client review')}" loading="lazy" decoding="async"${editing()?'':' data-a="zoom"'}>${editing()?`<button class="rx" data-a="rimdel" data-i="${i}" data-j="${j}" aria-label="Remove image">✕</button>`:''}</div>`).join('')}<figcaption>${r.title||editing()?`<b${E(`reviews.${i}.title`)}>${esc(tr(r.title))}</b>`:''}${r.text||editing()?`<span${E(`reviews.${i}.text`)}>${esc(tr(r.text))}</span>`:''}${r.name||editing()?`<em${E(`reviews.${i}.name`)}>${esc(r.name)}</em>`:''}</figcaption></figure>`).join('')}</div>`:`<p class="empty">${esc(tr('No reviews have been added yet.'))}</p>`}</section>`}
const route=(h,p)=>h=='about'?about():h=='contact'?contact():h=='services'?services():h=='reviews'?reviews():h=='portfolio'?portfolio():p?page(p):home();
const aboutCard=(c,ci)=>`<div class="card">${c.img?`<img class="abi" src="${esc(c.img)}" alt="" loading="lazy" decoding="async">`:''}<h3${E(`about.cards.${ci}.h`)}>${esc(tr(c.h))}</h3>${c.sub||editing()?`<p class="abs"${E(`about.cards.${ci}.sub`)}>${esc(tr(c.sub))}</p>`:''}${c.text||editing()?`<p class="abt"${E(`about.cards.${ci}.text`)}>${esc(tr(c.text))}</p>`:''}${c.lines.length?`<ul>${c.lines.map((l,li)=>`<li${E(`about.cards.${ci}.lines.${li}`)}>${esc(tr(l))}</li>`).join('')}</ul>`:''}${editing()?`<div class="estrip"><button class="tog" data-a="aup" data-i="${ci}">↑</button><button class="tog" data-a="adn" data-i="${ci}">↓</button><button class="tog" data-a="aimg" data-i="${ci}">${c.img?'Change':'+'} image</button>${c.img?`<button class="tog" data-a="aimgx" data-i="${ci}">Remove image</button>`:''}<button class="tog" data-a="adel" data-i="${ci}">Delete section</button></div>`:''}</div>`;
const about=()=>`<section class="pg"><header class="ph"><h2>${esc(tr('About'))}</h2><p class="lead"${E('about.intro')}>${esc(tr(st.about.intro))}</p></header><div class="cols">${st.about.cards.map(aboutCard).join('')}</div>${editing()?`<p><button class="tog" data-a="aadd">+ Add section</button></p>`:''}</section>`;
IC.link='<path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>';
IC.youtube='<rect x="2.5" y="5.5" width="19" height="13" rx="4" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M10 9l5 3-5 3z"/>';
const iconOf=u=>{u=String(u).toLowerCase();return /^mailto:/.test(u)?'mail':/^tel:/.test(u)?'phone':/wa\.me|whatsapp/.test(u)?'whatsapp':/facebook\.com|fb\.com|fb\.me/.test(u)?'facebook':/linkedin\.com/.test(u)?'linkedin':/behance\.net/.test(u)?'behance':/instagram\.com/.test(u)?'instagram':/youtube\.com|youtu\.be/.test(u)?'youtube':'link'},fixUrl=u=>/^(https?:|mailto:|tel:|#)/i.test(u)?u:'https://'+u;
function links(){return st.links.filter(l=>l.url).map(l=>{const k=iconOf(l.url),u=fixUrl(l.url);return `<span class="icw"><a class="ic" href="${esc(u)}" ${/^https?:/i.test(u)?'target="_blank" rel="noopener"':''} aria-label="${esc(l.title||k)}" title="${esc(l.title||k)}"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">${IC[k]||IC.link}</svg></a>${l.title?`<small>${esc(l.title)}</small>`:''}</span>`}).join('')}
const contact=()=>`<section class="pg"><header class="ph"><h2>${esc(tr('Contact'))}</h2><p class="lead">${esc(tr('Tell me about your project. I will reply by email.'))}</p></header><div class="icons">${links()}</div>${st.contact.address?`<p class="lead"${E('contact.address')}>${esc(tr(st.contact.address))}</p>`:''}<p><button class="btn" data-hire>${esc(tr('Hire me'))}</button></p></section>`;
function render(){try{render0()}catch(e){console.error(e);$('#app').innerHTML='<div style="padding:32px;font:16px system-ui;color:#ddd">Something went wrong while showing this page.<br><br><button class="btn" onclick="location.reload()">Reload</button></div>'}}
function render0(){theme();document.body.classList.toggle("ed",editing());document.title=tr(st.brand.name)+' – '+st.brand.roles.slice(0,3).map(r=>tr(r)).join(', ');const tc=$('meta[name=theme-color]');if(tc)tc.content=tcur().bg.startsWith('rgba')?'#0D0A1F':tcur().bg;document.documentElement.lang=lang;document.documentElement.dir=lang=='ar'?'rtl':'ltr';const h=location.hash.slice(1)||'home',p=vis().find(x=>x.id==h);$('#app').innerHTML=head()+`<main tabindex="-1">${route(h,p)}</main><footer><span>© 2026 ${esc(tr(st.brand.name))}</span><button type="button" class="admlnk" data-a="gear">Admin</button></footer>`}
let t0;const soft=()=>{clearTimeout(t0);t0=setTimeout(render,250)};
addEventListener('hashchange',()=>{render();scrollTo(0,0);const m=$('main');if(m)m.focus({preventScroll:true})});
addEventListener('scroll',()=>{const h=document.documentElement,e=$('#ph');if(e)e.style.width=h.scrollTop/Math.max(1,h.scrollHeight-h.clientHeight)*100+'%'},{passive:true});
let AC;function blip(){if(st.sound===false)return;try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();const n=AC.currentTime,o=AC.createOscillator(),g=AC.createGain();o.type='sine';o.frequency.setValueAtTime(760,n);o.frequency.exponentialRampToValueAtTime(520,n+.09);g.gain.setValueAtTime(.0001,n);g.gain.exponentialRampToValueAtTime(.06,n+.01);g.gain.exponentialRampToValueAtTime(.0001,n+.14);o.connect(g).connect(AC.destination);o.start(n);o.stop(n+.16)}catch(e){}}
document.addEventListener('click',e=>{if(e.target.closest('a,button,figure,select')&&!e.target.closest('#adm')&&!/^(VIDEO|AUDIO)$/.test(e.target.tagName))blip()},true);
let lastF;const closeM=()=>{$('#modal').innerHTML='';if(lastF&&lastF.focus)lastF.focus()};
function hire(){lastF=document.activeElement;$('#modal').innerHTML=`<div class="ov"><form class="mod" id="hf" role="dialog" aria-modal="true" aria-labelledby="hh" novalidate><button type="button" class="x" data-a="x" aria-label="${esc(tr('Close'))}">×</button><h3 id="hh">${esc(tr('Hire me'))}</h3><p style="margin:0;color:var(--mut);font-size:15px">${esc(tr('This form opens your email app or WhatsApp with your message ready. Nothing is sent until you press send there.'))}</p><label>${esc(tr('Your name'))} *<input name="n" required autocomplete="name"></label><label>${esc(tr('Your email'))} *<input name="e" type="email" required autocomplete="email" inputmode="email"></label><label>${esc(tr('WhatsApp'))}<input name="w" type="tel" autocomplete="tel" inputmode="tel" placeholder="+880…"></label><label>${esc(tr('What do you need help with?'))}<select name="s">${vis().map(p=>`<option value="${esc(p.title)}">${esc(tr(p.title))}</option>`).join('')}<option value="Other">${esc(tr('Other'))}</option></select></label><label>${esc(tr('Message'))} *<textarea name="m" rows="5" required minlength="10"></textarea></label><p id="fs" role="status" aria-live="polite" style="margin:0;min-height:1.5em;color:var(--em);font-size:15px"></p><div class="cta"><button class="btn">${esc(tr('Send via email'))}</button><button type="button" class="btn ghost" data-a="wa">${esc(tr('Send via WhatsApp'))}</button></div></form></div>`;$('#hf [name=n]').focus()}
const chk=f=>{const d=new FormData(f),v=k=>String(d.get(k)||'').trim();if(!v('n'))return['n','Please enter your name.'];if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v('e')))return['e','Please enter a valid email address.'];if(v('w')&&!/^\+?[\d\s-]{7,16}$/.test(v('w')))return['w','Please enter a valid WhatsApp number or leave it empty.'];if(v('m').length<10)return['m','Please write a message (at least 10 characters).']};
function vf(f){f.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));const r=chk(f);if(r){const el=f.elements[r[0]];el.setAttribute('aria-invalid','true');el.focus();$('#fs').textContent=tr(r[1]);return false}return true}
document.addEventListener('keydown',e=>{const m=$('#modal .mod');if(!m)return;if(e.key=='Escape')closeM();if(e.key=='Tab'){const f=[...m.querySelectorAll('button,input,select,textarea')],a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement==a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement==z){e.preventDefault();a.focus()}}});
const body=d=>`Name: ${d.get('n')}\nEmail: ${d.get('e')}\nWhatsApp: ${d.get('w')}\nService: ${d.get('s')}\n\n${d.get('m')}`;
document.addEventListener('submit',e=>{if(e.target.id=='hf'){e.preventDefault();const f=e.target;if(!vf(f))return;const d=new FormData(f);$('#fs').textContent=tr('Opening your email app. If nothing opens, email me directly at')+' '+st.contact.email;location.href='mailto:'+st.contact.email+'?subject='+encodeURIComponent('Hire inquiry: '+d.get('s'))+'&body='+encodeURIComponent(body(d))}});
const toast=(t,ms=2000)=>{const e=$('#toast');e.textContent=t;e.className='on';clearTimeout(toast.t);toast.t=setTimeout(()=>e.className='',ms)};
function copyLink(){const u=st.siteUrl||location.href.split('#')[0],ok=()=>toast(tr('Link copied')),fb=()=>{const t=document.createElement('textarea');t.value=u;t.style.cssText='position:fixed;opacity:0';document.body.appendChild(t);t.select();let r=false;try{r=document.execCommand('copy')}catch(e){}t.remove();r?ok():toast(tr('Copy this link:')+' '+u,6000)};if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(u).then(ok,fb);else fb()}
let wt;function enter(){clearTimeout(wt);const w=$('.wl');if(!w)return;w.classList.add('out');setTimeout(()=>{$('#welcome').innerHTML=''},450)}
function welcome(force){if(st.welcome===false&&!force)return;if(!force){try{if(sessionStorage.getItem('wel'))return}catch(e){}}
$('#welcome').innerHTML=`<div class="wl" role="dialog" aria-modal="true" aria-label="${esc(tr('Welcome'))}"><img src="${esc(st.brand.logo)}" alt=""><p class="wk">${esc(tr('Welcome'))}</p><div class="wn">${esc(tr(st.brand.name))}</div><p class="wi">${esc(tr(st.brand.intro))}</p><div class="wlang">${[['en','English'],['bn','বাংলা'],['ar','العربية']].map(l=>`<button class="tog" aria-pressed="${lang==l[0]}" data-a="wlang" data-x="${l[0]}">${l[1]}</button>`).join('')}</div><button class="btn" data-a="enter" id="we">${esc(tr('Enter site'))}</button></div>`;try{sessionStorage.setItem('wel','1')}catch(e){}clearTimeout(wt);wt=setTimeout(enter,6500);$('#we').focus()}
