const msg=t=>{const m=$('#msg');if(m)m.textContent=t;else toast(t,3500)},aerr=t=>{const e=$('#aer');if(e)e.textContent=t};
const I=(l,p,t='text')=>`<label>${l}<input type="${t}" data-b="${p}" value="${esc(get(p))}"></label>`;
const X=(l,p,ln)=>`<label>${l}<textarea rows="4" data-b="${p}" ${ln?'data-l':''}>${esc(ln?(get(p)||[]).join('\n'):get(p))}</textarea></label>`;
