const designTab=()=>'<h4>Interfaces: tap one to preview, then press Save</h4><div class="thg">'+TH.map((t,i)=>`<button class="thm" data-a="theme" data-x="${i}" aria-pressed="${(st.theme||0)==i}" style="background:${t.bg.startsWith('rgba')?'#0D0A1F':t.bg};color:${t.tx};border-color:${t.c1}"><i style="background:${t.c1}"></i><i style="background:${t.c2}"></i>${i+1}. ${t.n}</button>`).join('')+'</div><h4>Fonts</h4>'+S('Headline font','brand.fh',fonts())+S('Sub-headline font','brand.fs',fonts())+S('Body font','brand.fb',fonts())+'<div class="box"><label>Add a custom font: name<input id="fn" placeholder="Ador Noirrit"></label><button class="tog" data-a="addfont">Upload font file (.ttf .otf .woff2)</button></div><h4>Main color</h4>'+`<label>Override<input type="color" data-b="brand.c1" value="${st.brand.c1||tcur().c1}"></label><button class="tog" data-a="resetc">Use the interface color</button><label class="row"><input type="checkbox" data-b="sound" ${st.sound!==false?'checked':''}> Click sound</label><label class="row"><input type="checkbox" data-b="welcome" ${st.welcome!==false?'checked':''}> Welcome screen</label>`;
const siteTab=()=>U('Change logo','brand.logo')+U('Change photo','brand.photo')+['photo','logo'].map(k=>`<div class="box"><label>Or paste a direct image link for the ${k}<input id="ul-${k}" placeholder="https://…/image.jpg"></label><button class="tog" data-a="useurl" data-path="brand.${k}" data-in="ul-${k}">Use this link</button></div>`).join('')+I('Name','brand.name')+X('Identity lines (one per line)','brand.roles',1)+X('Intro text','brand.intro')+'<h4>Software list (home)</h4>'+X('One per line','tools',1)+I('Website link (used by the copy-link button)','siteUrl')+'<h4>Contact</h4>'+I('Email','contact.email')+I('WhatsApp number (with country code)','contact.wa')+X('Address','contact.address');
function pagesTab(){const n=ui.pg,p=st.pages[n],k=ui.fo['a'+n]||0,f=p.folders[k]||{items:[]},b=`pages.${n}.`;return `<label>Page<select data-ui="pg">${st.pages.map((x,i)=>`<option value="${i}" ${i==n?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><div class="row"><button class="tog" data-a="addPage">+ Add page</button><button class="tog" data-a="delPage">Delete this page</button></div>`+I('Title',b+'title')+X('Description',b+'lede')+S('Layout design',b+'layout',LAY)+S('Menu: portfolio = inside the Portfolio dropdown, main = its own menu item, hidden = no menu item',b+'group',['portfolio','main','hidden'])+`<label>Page color<input type="color" data-b="${b}accent" value="${/^#/.test(p.accent)?p.accent:tcur().c1}"></label><button class="tog" data-a="resetAc">Use the interface color</button><label class="row"><input type="checkbox" data-b="${b}show" ${p.show?'checked':''}> Show this page on the site</label><h4>Sub-folders</h4><label>Folder<select data-ui="fo">${p.folders.map((x,i)=>`<option value="${i}" ${i==k?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`+(p.folders[k]?I('Rename folder',`${b}folders.${k}.name`):'')+`<div class="row"><button class="tog" data-a="addFolder">+ Add folder</button><button class="tog" data-a="delFolder">Delete folder</button></div><h4>Projects in this folder</h4>`+f.items.map((it,j)=>{const q=`${b}folders.${k}.items.${j}.`;return `<div class="box">${I('Title',q+'title')}${I('Description',q+'desc')}${it.type=='link'?I('Link',q+'url'):''}<div class="row"><button class="tog" data-up="${q}src">Replace file</button><button class="tog" data-a="delItem" data-x="${j}">Delete</button><span class="sub">${it.type}</span></div></div>`}).join('')+(p.folders[k]?`<button class="btn" data-upm>+ Upload projects (image, video, audio)</button><div class="box"><label>Add by link: YouTube, Vimeo, Facebook video, Behance, Instagram, or a direct file link<input id="lk1" placeholder="https://"></label><button class="tog" data-a="ladd" data-pi="${n}" data-fi="${k}" data-in="lk1">Add link</button></div>`:'')}
const aboutTab=()=>X('Intro','about.intro')+st.about.cards.map((c,i)=>`<div class="box">${U('Section image',`about.cards.${i}.img`)}${I('Heading',`about.cards.${i}.h`)}${I('Subheading',`about.cards.${i}.sub`)}${X('Paragraph',`about.cards.${i}.text`)}${X('List lines (one per line)',`about.cards.${i}.lines`,1)}<div class="row"><button class="tog" data-a="aup" data-i="${i}">↑</button><button class="tog" data-a="adn" data-i="${i}">↓</button>${c.img?`<button class="tog" data-a="aimgx" data-i="${i}">Remove image</button>`:''}<button class="tog" data-a="adel" data-i="${i}">Delete section</button></div></div>`).join('')+'<button class="btn" data-a="aadd">+ Add section</button>';
const mvB=(a,i)=>`<button class="tog" data-a="${a}up" data-i="${i}">↑</button><button class="tog" data-a="${a}dn" data-i="${i}">↓</button><button class="tog" data-a="${a}del" data-i="${i}">Delete</button>`;
const linksTab=()=>'<p class="sub">Add as many links as you like. The icon is chosen from the address (Facebook, YouTube, WhatsApp, email…). Any other site gets a link icon.</p>'+st.links.map((l,i)=>`<div class="box">${I('Name',`links.${i}.title`)}${I('Address (https://…, mailto:…, tel:…)',`links.${i}.url`)}<div class="row">${mvB('l',i)}</div></div>`).join('')+'<button class="btn" data-a="lnadd">+ Add link</button>';
const svcTab=()=>st.services.map((s,i)=>`<div class="box">${I('Title',`services.${i}.title`)}${X('Short description',`services.${i}.text`)}<label>Opens page<select data-b="services.${i}.target"><option value="">(none)</option>${st.pages.map(p=>`<option value="${esc(p.id)}" ${s.target==p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><div class="row">${mvB('s',i)}</div></div>`).join('')+'<button class="btn" data-a="sadd">+ Add service</button>';
const revTab=()=>'<button class="btn" data-a="radd">+ Add review (upload screenshots)</button>'+(st.reviews.length?'':'<p class="sub">No reviews yet. Upload a screenshot of a client message to start.</p>')+st.reviews.map((r,i)=>`<div class="box">${I('Title',`reviews.${i}.title`)}${I('Client name (optional)',`reviews.${i}.name`)}${X('Review text (optional)',`reviews.${i}.text`)}<div class="row">${r.images.map((m,j)=>`<span class="row"><img class="th" src="${esc(m.src)}" alt=""><button class="tog" data-a="rimdel" data-i="${i}" data-j="${j}">✕</button></span>`).join('')}</div><div class="row"><button class="tog" data-a="rimg" data-i="${i}">+ Image</button><button class="tog" data-a="rup" data-i="${i}">↑</button><button class="tog" data-a="rdn" data-i="${i}">↓</button><label class="row"><input type="checkbox" data-b="reviews.${i}.show" ${r.show!==false?'checked':''}> Visible</label><button class="tog" data-a="rdel" data-i="${i}">Delete</button></div></div>`).join('');
function strs(){const o=new Set([...UIS,st.brand.name,...st.brand.roles,st.brand.intro,st.contact.address,st.about.intro]);st.about.cards.forEach(c=>{o.add(c.h);c.lines.forEach(l=>o.add(l))});st.pages.forEach(p=>{o.add(p.title);o.add(p.lede);p.folders.forEach(f=>{o.add(f.name);f.items.forEach(i=>{o.add(i.title);o.add(i.desc)})})});o.delete('');return [...o]}
