function parseLink(raw){let u;raw=(raw||'').trim();if(!raw)return null;if(/\s/.test(raw))return null;try{u=new URL(/^https?:\/\//i.test(raw)?raw:'https://'+raw)}catch(e){return null}if(!/\./.test(u.hostname))return null;
const h=u.hostname.replace(/^(www|m)\./,''),p=u.pathname,q=u.searchParams;let m;const file=decodeURIComponent(p.split('/').pop()||'');
if(h=='youtu.be'||h.endsWith('youtube.com')){let id=h=='youtu.be'?p.slice(1):(q.get('v')||((m=p.match(/^\/(?:shorts|embed|live)\/([\w-]{6,})/))&&m[1]));id=(id||'').split(/[/?]/)[0];if(!id)return{type:'link',platform:'youtube',url:u.href,title:'YouTube'};return{type:'embed',platform:'youtube',url:u.href,src:'https://www.youtube-nocookie.com/embed/'+id+'?rel=0&autoplay=1',thumb:'https://i.ytimg.com/vi/'+id+'/hqdefault.jpg',title:'YouTube video'}}
if(h=='vimeo.com'||h=='player.vimeo.com'){m=p.match(/(\d{5,})/);if(m)return{type:'embed',platform:'vimeo',url:u.href,src:'https://player.vimeo.com/video/'+m[1]+'?autoplay=1',title:'Vimeo video'};return{type:'link',platform:'vimeo',url:u.href,title:'Vimeo'}}
if(h.endsWith('facebook.com')||h=='fb.watch'){if(h=='fb.watch'||/\/(videos?|reel|watch)\b/.test(p))return{type:'embed',platform:'facebook',url:u.href,src:'https://www.facebook.com/plugins/video.php?show_text=false&autoplay=1&href='+encodeURIComponent(u.href),title:'Facebook video'};return{type:'link',platform:'facebook',url:u.href,title:'Facebook'}}
const N={'behance.net':'behance','instagram.com':'instagram','tiktok.com':'tiktok','dribbble.com':'dribbble','linkedin.com':'linkedin'};
for(const k in N)if(h==k||h.endsWith('.'+k)){const s=decodeURIComponent(p.split('/').filter(Boolean).pop()||'').replace(/[-_+]+/g,' ').replace(/^\d+\s*/,'').trim();return{type:'link',platform:N[k],url:u.href,title:s&&!/^\d+$/.test(s)?s.replace(/\b\w/g,c=>c.toUpperCase()):PL[N[k]]+' project'}}
if(/\.(mp4|webm|mov)$/i.test(p))return{type:'video',platform:'link',url:u.href,src:u.href,title:file};if(/\.(mp3|wav|ogg|m4a)$/i.test(p))return{type:'audio',platform:'link',url:u.href,src:u.href,title:file};if(/\.(jpe?g|png|webp|gif|avif|svg)$/i.test(p))return{type:'image',platform:'link',url:u.href,src:u.href,title:file};
return{type:'link',platform:'link',url:u.href,title:h}}
const testMedia=(u,k)=>new Promise(r=>{const e=k=='image'?new Image():document.createElement(k),t=setTimeout(()=>r(false),7000);e.onerror=()=>{clearTimeout(t);r(false)};if(k=='image')e.onload=()=>{clearTimeout(t);r(true)};else{e.onloadedmetadata=()=>{clearTimeout(t);r(true)};e.preload='metadata'}e.src=u});
